// ---- Configuration (single place to tune the rules) ----
const CONFIG = {
  rulesVersion: '2026.10',
  companyName: 'Northstar Electronics',
  fraudOpsEmail: 'fraud-ops@example.com',
  thresholds: { highOrderValue: 1000, newEmailDays: 14, cardAttempts: 4, orders24h: 5, largeItemCount: 8, high: 70, medium: 40 },
  weights: { country_mismatch: 25, high_order_value: 20, new_email: 15, multiple_card_attempts: 25, multiple_orders_24h: 15, shipping_billing_mismatch: 15, large_item_count: 10 }
};
const T = CONFIG.thresholds;
const W = CONFIG.weights;

// ---- Validation ----
const b = $json.body ?? $json;
const required = ['order_id', 'customer_email', 'amount', 'currency', 'country', 'ip_country'];
for (const key of required) {
  if (b[key] === undefined || b[key] === null || String(b[key]).trim() === '') throw new Error(`${key} is required`);
}

const customerEmail = String(b.customer_email).trim().toLowerCase();
if (customerEmail.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(customerEmail)) throw new Error('customer_email is invalid');

const num = (v, def) => {
  if (v === undefined || v === null || v === '') return def;
  const n = Number(v);
  return Number.isFinite(n) ? n : def;
};
const nonNeg = (v, def) => Math.max(0, num(v, def));
const toBool = v => v === true || ['true', '1', 'yes', 'y'].includes(String(v).trim().toLowerCase());

const amount = Number(b.amount);
if (!Number.isFinite(amount) || amount < 0) throw new Error('amount must be a non-negative number');

const currency = String(b.currency).trim().toUpperCase();
if (!/^[A-Z]{3}$/.test(currency)) throw new Error('currency must be a 3-letter ISO 4217 code');

const country = String(b.country).trim().toUpperCase();
const ipCountry = String(b.ip_country).trim().toUpperCase();
if (!/^[A-Z]{2}$/.test(country)) throw new Error('country must be a 2-letter ISO 3166-1 code');
if (!/^[A-Z]{2}$/.test(ipCountry)) throw new Error('ip_country must be a 2-letter ISO 3166-1 code');

const cardAttempts = nonNeg(b.card_attempts_24h, 0);
const orders24h = nonNeg(b.orders_24h, 0);
const emailAge = nonNeg(b.email_age_days, 365);
const items = nonNeg(b.items_count, 1);
const shippingBillingMismatch = toBool(b.shipping_billing_mismatch);

// ---- Deterministic risk scoring ----
const signals = [];
let score = 0;
function add(name, triggered) {
  if (triggered) { score += W[name]; signals.push({ name, points: W[name] }); }
}
add('country_mismatch', country !== ipCountry);
add('high_order_value', amount >= T.highOrderValue);
add('new_email', emailAge < T.newEmailDays);
add('multiple_card_attempts', cardAttempts >= T.cardAttempts);
add('multiple_orders_24h', orders24h >= T.orders24h);
add('shipping_billing_mismatch', shippingBillingMismatch);
add('large_item_count', items >= T.largeItemCount);

score = Math.min(score, 100);
const risk_level = score >= T.high ? 'HIGH' : score >= T.medium ? 'MEDIUM' : 'LOW';

return [{
  json: {
    event_id: `FRD-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    received_at: new Date().toISOString(),
    rules_version: CONFIG.rulesVersion,
    company_name: CONFIG.companyName,
    fraud_ops_email: CONFIG.fraudOpsEmail,
    order_id: String(b.order_id).trim().slice(0, 100),
    customer_email: customerEmail,
    amount,
    currency,
    country,
    ip_country: ipCountry,
    ip_address: String(b.ip_address ?? '').trim().slice(0, 64),
    card_attempts_24h: cardAttempts,
    orders_24h: orders24h,
    email_age_days: emailAge,
    items_count: items,
    shipping_billing_mismatch: shippingBillingMismatch,
    risk_score: score,
    risk_level,
    triggered_rules: signals,
    signals_summary: signals.map(s => `${s.name} (+${s.points})`).join(', ') || 'none'
  }
}];

const src = $('Normalize Order & Build Risk Signals').first().json;
const aiSkipped = src.risk_level === 'LOW';   // LOW orders skip the LLM entirely
const raw = String($json.output ?? '').trim();
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');

const defaultAction = { HIGH: 'manual_review', MEDIUM: 'monitor', LOW: 'allow' }[src.risk_level];
const fallback = {
  assessment: aiSkipped
    ? 'Low risk score - AI analysis not required.'
    : 'AI assessment unavailable - decision based on deterministic risk score only.',
  primary_concerns: [],
  recommended_action: defaultAction,
  customer_safe_message: 'Your order is undergoing a routine payment verification. We will contact you if we need any additional information. Thank you for your patience.'
};

let ai = fallback;
let aiUsed = false;
try {
  if (start >= 0 && end > start) {
    ai = { ...fallback, ...JSON.parse(raw.slice(start, end + 1)) };
    aiUsed = true;
  }
} catch (e) {
  ai = fallback;
}

// Sanitizers for untrusted LLM output
const stripUrls = s => String(s).replace(/(https?:\/\/|www\.)\S+/gi, '').replace(/[ \t]{2,}/g, ' ').trim();
const noMentions = s => String(s).replace(/<[!@#]/g, '<');   // no @channel / @here injection into Slack

// Guardrails: AI may not undercut the deterministic score
const allowed = ['allow', 'monitor', 'manual_review', 'block'];
let action = allowed.includes(ai.recommended_action) ? ai.recommended_action : defaultAction;
if (src.risk_level === 'HIGH' && ['allow', 'monitor'].includes(action)) action = 'manual_review';
if (src.risk_level === 'MEDIUM' && ['allow', 'block'].includes(action)) action = action === 'block' ? 'manual_review' : 'monitor';
if (src.risk_level === 'LOW' && action !== 'allow') action = 'allow';

const customerMessage = stripUrls(ai.customer_safe_message ?? '').slice(0, 1000) || fallback.customer_safe_message;

// Whitelist AI fields - never let AI overwrite risk_score / risk_level / order data
return [{
  json: {
    ...src,
    assessment: noMentions(ai.assessment ?? fallback.assessment).slice(0, 2000),
    primary_concerns: Array.isArray(ai.primary_concerns) ? ai.primary_concerns.map(c => noMentions(c)).slice(0, 10) : [],
    recommended_action: action,
    customer_safe_message: customerMessage,
    ai_used: aiUsed,
    decision_source: aiUsed ? 'rules+ai' : 'rules',
    analyzed_at: new Date().toISOString()
  }
}];

